const routePart = () => location.pathname.split('/').filter(Boolean).filter(p => p !== 'tools')[0] || '';
const initialTool = (): Tool => { const candidate = routePart().replace('_ipv6', ''); return TOOLS.includes(candidate as Tool) ? candidate as Tool : 'ping'; };
