// Same host:port interaction as the original Tcping form; bare IPv6 stays intact.
export function splitTcpingTarget(value: string, fallbackPort = 80) {
  const target = normalizeTargetInput(value).trim();
  const bracket = target.match(/^\[([^\]]+)\](?::(.*))?$/);
  const hostPort = target.match(/^([^:]+):([^:]*)$/);
  const match = bracket || hostPort;
  const port = match?.[2] === undefined ? fallbackPort : Number(match[2]);
  if (!Number.isInteger(port) || port < 1 || port > 65535 || match?.[2] !== undefined && !/^\d+$/.test(match[2])) throw new Error('端口必须为 1 至 65535 的整数');
  return { target: match ? match[1] : target, port };
}
